          "condition": {
            "mode": "glide_scripted_query",
            "value": "(function execute(table) {\n\n    var gr = new GlideRecordSecure(table);\n\n    if (vaInputs.lookup_claim) {\n        gr.addQuery('claim', vaInputs.lookup_claim.getValue('sys_id'));\n    }\n\n    gr.query();\n\n    if (gr.next()) {\n        return gr;\n    }\n\n    return null;\n\n})(table);"
